mapper.select:
SELECT * FROM orbit_account_scope_audit WHERE target_tenant_id=#{tenant}
AND created_at < #{cutoff}
AND action LIKE CONCAT('%',#{q},'%') ESCAPE '!'
AND actor_subject_id=#{operator}
AND created_at >= #{from}
AND created_at < #{until}
AND (created_at < #{afterAt} OR (created_at=#{afterAt} AND id < #{afterId}))
ORDER BY created_at DESC,id DESC LIMIT 201

SELECT EXISTS(SELECT 1 FROM orbit_account_scope_member m LEFT JOIN orbit_account_scope_directory d ON d.tenant_id=m.tenant_id AND d.id=m.account_id WHERE m.tenant_id=#{tenant} AND m.snapshot_id=#{id} AND (d.id IS NULL
OR NOT (d.operator_user_id <=> #{access.subject})
OR d.owner_team_id IS NULL OR d.owner_team_id NOT IN #{team}
OR 1=1
) LIMIT 1 FOR SHARE)

SELECT account_id AS id,external_id,name,directory_account_revision AS revision
FROM orbit_account_scope_member WHERE tenant_id=#{tenant} AND snapshot_id=#{id}
AND account_id > #{after}
AND (name LIKE CONCAT('%',#{escaped},'%') ESCAPE '!' OR external_id=#{q})
ORDER BY account_id LIMIT #{limit} FOR SHARE

SELECT id,external_id,name,revision,account_status,auth_status,source_state
FROM orbit_account_scope_directory WHERE tenant_id=#{tenant}

    
    AND operator_user_id=#{access.subject}
    
        AND owner_team_id IN #{team}
    
    AND 1=0


    
        AND id IN #{id}
    
    
        AND (name LIKE CONCAT('%',#{request.escapedQ},'%') ESCAPE '!' OR external_id=#{request.q})
        AND account_status=#{request.status}
        AND auth_status=#{request.authStatus}
        AND operator_user_id=#{request.operator}
        AND vendor_id=#{request.vendor}
    

ORDER BY id LIMIT 50001 FOR SHARE
